(()=>{'use strict';
const source=globalThis.ShenluStoryAudioBindings||{};
globalThis.ShenluDemoStoryAudioSource=source;
const supported=new Set(['none','zh-Hant','en','ja','ko','zh-Hans']);
const keys=new WeakMap();
for(const [route,r] of Object.entries(source))for(const [chapter,c] of Object.entries(r.chapters||{})){
  for(const segment of ['before','after'])if(c[segment])keys.set(c[segment],route+'/'+chapter+'/'+segment);
  (c.options||[]).forEach((o,i)=>{for(const segment of ['reply','afterReply'])if(o[segment])keys.set(o[segment],route+'/'+chapter+'/options/'+i+'/'+segment);});
}
function selected(){const locale=localStorage.getItem('shenlu-demo:locale')||'zh-Hant',stored=localStorage.getItem('shenlu-demo:voice');return supported.has(stored)?stored:supported.has(locale)?locale:'zh-Hant';}
function sync(){const voice=selected();globalThis.ShenluDemoVoiceLocale=voice;globalThis.ShenluStoryAudioBindings=['zh-Hant','zh-Hans'].includes(voice)?source:{};return voice;}
const messages={"zh-Hant":{"packPreview":"AI配音","previewNote":"配音與字幕語言可分別選擇。","detailsTitle":"關於配音","detailsBody":"配音由AI生成。 繁中與簡中共用中文配音；字幕可分別選擇。","missing":"這段尚無所選語音。可看字幕，按「下一句」繼續。","silent":"未選配音。可按「下一句」閱讀。","error":"音檔暫時無法播放。可按「下一句」閱讀。","listen":"聆聽旁白","resume":"繼續聆聽","next":"下一句","continue":"繼續","previous":"上一句","show":"顯示字幕","hide":"隱藏字幕"},"en":{"packPreview":"AI voices","previewNote":"Choose voice and subtitle languages separately.","detailsTitle":"About voices","detailsBody":"Voices are AI-generated. Traditional and Simplified Chinese share Chinese voices. Choose subtitles separately.","missing":"This scene has no audio in the selected language. Read the subtitles and choose Next line.","silent":"No voice selected. Choose Next line to read.","error":"Audio is unavailable. Choose Next line to read.","listen":"Play narration","resume":"Resume narration","next":"Next line","continue":"Continue","previous":"Previous line","show":"Show subtitles","hide":"Hide subtitles"},"ja":{"packPreview":"AI音声","previewNote":"音声と字幕の言語は別々に選べます。","detailsTitle":"音声について","detailsBody":"音声はAIで生成しています。 繁体字版と簡体字版は中国語音声を共用します。字幕は別に選べます。","missing":"この場面には選んだ言語の音声がありません。字幕を読み、「次の文」で進めます。","silent":"音声なし。「次の文」で読み進めます。","error":"音声を再生できません。「次の文」で読み進めます。","listen":"音声を再生","resume":"音声を再開","next":"次の文","continue":"続ける","previous":"前の文","show":"字幕を表示","hide":"字幕を隠す"},"ko":{"packPreview":"AI 음성","previewNote":"음성과 자막 언어를 따로 선택할 수 있어요.","detailsTitle":"음성 안내","detailsBody":"음성은 AI로 만들었어요. 번체자와 간체자는 중국어 음성을 함께 써요. 자막은 따로 선택할 수 있어요.","missing":"이 장면에는 선택한 언어의 음성이 없어요. 자막을 읽고 다음 문장을 누르세요.","silent":"음성 없음. 다음 문장을 눌러 읽으세요.","error":"음성을 재생할 수 없어요. 다음 문장을 눌러 읽으세요.","listen":"음성 재생","resume":"음성 이어 듣기","next":"다음 문장","continue":"계속","previous":"이전 문장","show":"자막 표시","hide":"자막 숨기기"},"zh-Hans":{"packPreview":"AI配音","previewNote":"配音与字幕语言可分别选择。","detailsTitle":"关于配音","detailsBody":"配音由AI生成。 繁中与简中共用中文配音；字幕可分别选择。","missing":"这段还没有所选语言的配音。可看字幕，按“下一句”继续。","silent":"未选配音。可按“下一句”阅读。","error":"音频暂时无法播放。可按“下一句”阅读。","listen":"播放旁白","resume":"继续听","next":"下一句","continue":"继续","previous":"上一句","show":"显示字幕","hide":"隐藏字幕"}};
globalThis.ShenluDemoStoryAudio={
  selected:()=>sync(),
  set(voice){if(!supported.has(voice))return false;localStorage.setItem('shenlu-demo:voice',voice);sync();globalThis.dispatchEvent(new Event('demo-voice'));return true;},
  text(key){return(messages[globalThis.ShenluDemoI18n?.locale]||messages['zh-Hant'])[key]||key;},
  resolve(canonical){const voice=sync();if(voice==='none')return null;if(['zh-Hant','zh-Hans'].includes(voice))return canonical;
    const clip=globalThis.ShenluDemoStoryAudioCandidates?.[voice]?.[keys.get(canonical)];
    if(!clip||clip.sourceLineCount!==canonical.lines.length||clip.timings?.length!==canonical.lines.length)return null;
    return clip;
  },
  status:'candidate/partial; no human listening acceptance',
  canonicalSource:source
};sync();
})();
